@layer component {
  .input,
  .textarea,
  .select {
    padding: 0.5rem 1rem;
    width: 100%;
    font-weight: 500;

    &::placeholder {
      color: color-mix(in oklch, var(--c-text), transparent);
    }

    &:focus {
      border-color: color-mix(in oklch, var(--c-warn), var(--c-text));
      border-radius: var(--radius-alt);
    }
  }

  .input {
    height: 3rem;
  }

  .textarea {
    padding: 0.75rem 1rem;
    min-height: 100px;
    resize: vertical;
  }

  .selectWrapper {
    display: inline-block;
    position: relative;
    width: 100%;

    &::after {
      position: absolute;
      top: 40%;
      right: 1.25rem;
      transform: translateY(-40%) rotate(45deg);
      border-right: 0.2rem solid currentColor;
      border-bottom: 0.2rem solid currentColor;
      border-radius: var(--radius-alt);
      width: 1rem;
      height: 1rem;
      pointer-events: none;
      content: '';
    }
    &:focus-within::after {
      border-radius: var(--radius);
    }

    .select {
      appearance: none;
      cursor: pointer;
      padding-right: 3rem;
      height: 3rem;

      option:not(:disabled) {
        background-color: var(--c-bg);

        &:hover {
          background-color: var(--c-success);
        }
        &:checked {
          background-color: var(--c-primary);
        }
      }
    }
  }

  .checkbox {
    display: inline-block;
    vertical-align: middle;
    appearance: none;
    cursor: pointer;
    width: 1.5rem;
    height: 1.5rem;

    &:focus {
      border-radius: var(--radius-alt);
    }

    &:checked {
      background-color: var(--c-success);

      &::after {
        position: absolute;
        top: 45%;
        left: 50%;
        transform: translate(-50%, -50%);
        content: 'X';
        font-weight: 800;
        font-size: 1.2rem;
      }
    }
  }

  .radio {
    display: inline-block;
    vertical-align: middle;
    appearance: none;
    cursor: pointer;
    width: 1.5rem;
    height: 1.5rem;

    &:focus {
      border-radius: var(--radius-alt);

      &:checked::after {
        border-radius: var(--radius);
      }
    }

    &:checked {
      background-color: var(--c-success);

      &::after {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        box-shadow: 0 0 1px var(--c-bg);
        border-radius: var(--radius-alt);
        background-color: var(--c-text);
        width: 0.6rem;
        height: 0.6rem;
        content: '';
      }
    }
  }

  .switch {
    appearance: none;
    cursor: pointer;
    width: 3.5rem;
    height: 1.75rem;
    overflow: hidden;

    &::after {
      position: absolute;
      top: 0.125rem;
      left: 0.125rem;
      box-shadow: 0.25rem 0.25rem 0 var(--c-shadow);
      border-radius: var(--radius-alt);
      background-color: var(--c-text);
      width: 1.25rem;
      height: 1.25rem;
      content: '';
    }

    &:focus {
      border-radius: var(--radius-alt);
    }

    &:checked {
      background-color: var(--c-success);

      &::after {
        left: 1.875rem;
        border-radius: var(--radius);
      }
    }
  }

  .slider {
    appearance: none;
    cursor: pointer;
    margin: 0.375rem 0;
    background-color: var(--c-muted);
    width: 100%;
    height: 1rem;

    &:focus {
      border-radius: var(--radius-alt);
    }

    &::-webkit-slider-thumb,
    &::-moz-range-thumb {
      appearance: none;
      box-shadow: 0.25rem 0.25rem 0 var(--c-shadow);
      border: 0.125rem solid var(--c-border);
      border-radius: var(--radius-alt);
      background-color: var(--c-warn);
      width: 1.75rem;
      height: 1.75rem;
    }
    &:hover {
      &::-webkit-slider-thumb,
      &::-moz-range-thumb {
        border-radius: var(--radius);
      }
    }

    &:focus-visible {
      &::-webkit-slider-thumb,
      &::-moz-range-thumb {
        outline: 0.25rem solid oklch(from color-mix(in oklch, var(--c-primary), var(--c-success)) 0.69 calc(c * 1.3) h);
        border-radius: var(--radius);
      }
    }
  }

  :is(.input, .textarea, .select, .checkbox, .radio, .switch, .slider):disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }

  .label {
    width: 100%;
    font-weight: 700;
    font-size: 0.875rem;
    line-height: 1.25rem;
    letter-spacing: 0.05em;

    &.inline {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
    }
  }
}

import { useCachedStyles } from '@/hook/useCachedStyles';
import { getCommonProps, type CommonProps } from '@/lib/utils';
import commonClasses from '@/style/common.module.css';
import classes from './input.module.css';

const INPUT_CLASSES = `${commonClasses.base} ${commonClasses.focusable} ${classes.input}`;
export function Input({ style, ...props }: CommonProps<'input'>) {
  const cStyles = useCachedStyles();

  return <input style={{ ...cStyles, ...style }} {...getCommonProps(props, INPUT_CLASSES)} />;
}

const TEXTAREA_CLASSES = `${commonClasses.base} ${commonClasses.focusable} ${classes.textarea}`;
export function Textarea({ style, ...props }: CommonProps<'textarea'>) {
  const cStyles = useCachedStyles();

  return <textarea style={{ ...cStyles, ...style }} {...getCommonProps(props, TEXTAREA_CLASSES)} />;
}

const SELECT_CLASSES = `${commonClasses.base} ${commonClasses.focusable} ${classes.select}`;
export function Select({ style, ...props }: CommonProps<'select'>) {
  const cStyles = useCachedStyles();

  return (
    <div className={classes.selectWrapper}>
      <select style={{ ...cStyles, ...style }} {...getCommonProps(props, SELECT_CLASSES)} />
    </div>
  );
}

const CHECKBOX_CLASSES = `${commonClasses.base} ${commonClasses.focusable} ${classes.checkbox}`;
export function Checkbox({ style, ...props }: Omit<CommonProps<'input'>, 'type'>) {
  const cStyles = useCachedStyles();

  return <input style={{ ...cStyles, ...style }} {...getCommonProps(props, CHECKBOX_CLASSES)} type='checkbox' />;
}

const RADIO_CLASSES = `${commonClasses.base} ${commonClasses.focusable} ${classes.radio}`;
export function Radio({ style, ...props }: Omit<CommonProps<'input'>, 'type'>) {
  const cStyles = useCachedStyles(true);

  return <input style={{ ...cStyles, ...style }} {...getCommonProps(props, RADIO_CLASSES)} type='radio' />;
}

const SWITCH_CLASSES = `${commonClasses.base} ${commonClasses.focusable} ${classes.switch}`;
export function Switch({ style, ...props }: Omit<CommonProps<'input'>, 'type' | 'role'>) {
  const cStyles = useCachedStyles(true);

  return (
    <input style={{ ...cStyles, ...style }} {...getCommonProps(props, SWITCH_CLASSES)} role='switch' type='checkbox' />
  );
}

const SLIDER_CLASSES = `${commonClasses.base} ${classes.slider}`;
export function Slider({ style, ...props }: Omit<CommonProps<'input'>, 'type'>) {
  const cStyles = useCachedStyles();

  return <input style={{ ...cStyles, ...style }} {...getCommonProps(props, SLIDER_CLASSES)} type='range' />;
}

export function Label({ inline, ...props }: CommonProps<'label', { inline?: boolean }>) {
  return <label {...getCommonProps(props, classes.label, inline && classes.inline)} />;
}
